// Bozze da approvare (etichetta «bozza») e problemi del sito («salute») mai mandati: una mail per ciascuno.
// La memoria resta solo quando il flusso è ATTIVO: le prove a mano con «Esegui» non la salvano.
const memoria = $getWorkflowStaticData('global');
const viste = new Set(memoria.viste || []);
const esc = (s) => String(s ?? '').replace(/[&<>]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' }[c]));
const out = [];
for (const it of $input.all()) {
  const i = it.json;
  const etichette = (i.labels || []).map((l) => l.name);
  if (i.pull_request || viste.has(i.number) || !etichette.some((l) => l === 'bozza' || l === 'salute')) continue;
  viste.add(i.number);
  const tipo = etichette.includes('salute') ? 'PROBLEMA' : etichette.includes('blog') ? 'Articolo da approvare' : 'Post da approvare';
  out.push({ json: {
    oggetto: `FreeLLMArena · ${tipo}: ${i.title.replace(/^(Articolo|Post social) da approvare: /, '')}`,
    html: `<p><a href="${esc(i.html_url)}">Apri su GitHub</a></p><pre style="white-space:pre-wrap;font-family:Arial,sans-serif;font-size:14px;line-height:1.5">${esc(i.body).slice(0, 12000)}</pre>`
  } });
}
memoria.viste = [...viste].slice(-500);
return out;
